import{_ as o,o as r,c as s,ag as n}from"./chunks/framework.D5hoimZQ.js";const l=JSON.parse('{"title":"🔬 科学日报 | 2026年9月18日 · 深度扩展","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/science-daily/2026-09-18.md","filePath":"science-log/src/science-daily/2026-09-18.md"}'),e={name:"science-log/src/science-daily/2026-09-18.md"};function a(g,t,c,i,d,u){return r(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="🔬-科学日报-2026年9月18日-·-深度扩展" tabindex="-1">🔬 科学日报 | 2026年9月18日 · 深度扩展 <a class="header-anchor" href="#🔬-科学日报-2026年9月18日-·-深度扩展" aria-label="Permalink to &quot;🔬 科学日报 | 2026年9月18日 · 深度扩展&quot;">​</a></h1><blockquote><p>来源：<strong>事后重建版简讯</strong>（science-log/src/reconstructed/2026-09-18.md，共 10 条：科学前沿 5 + AI 前沿 5；科学取自 Science Advances / PNAS 当日刊出，AI 取自当日 arXiv cs.AI 提交） 分析日期：2026-09-18 版本：扩展版（10 条深度 + 交叉关联） ⚠️ 本日简讯为<strong>事后重建版</strong>（2026-11-05 按 arXiv/CrossRef 日期回溯生成，非当日发布原文，不代表历史原貌）</p></blockquote><hr><h2 id="🔬-一、科学前沿" tabindex="-1">🔬 一、科学前沿 <a class="header-anchor" href="#🔬-一、科学前沿" aria-label="Permalink to &quot;🔬 一、科学前沿&quot;">​</a></h2><h3 id="_1-冲击压缩下纳米多晶金刚石达到-92-gpa-的超高流动强度" tabindex="-1">1. 冲击压缩下纳米多晶金刚石达到 92 GPa 的超高流动强度 <a class="header-anchor" href="#_1-冲击压缩下纳米多晶金刚石达到-92-gpa-的超高流动强度" aria-label="Permalink to &quot;1. 冲击压缩下纳米多晶金刚石达到 92 GPa 的超高流动强度&quot;">​</a></h3><p><strong>原文</strong>：极端压力与温度下，连金刚石这类硬脆材料也会发生塑性流动，但其流动强度的上限长期不确定，主导变形机制也存争议。作者用飞秒原位 X 射线衍射结合大规模分子动力学模拟，直接测量冲击压缩纳米多晶金刚石的强度：在 212 ± 6 GPa 的应力下达到峰值流动强度 92 ± 3 GPa。结果表明，层错介导的强化是关键——高压下多种竞争性变形机制与热力学效应交织，反而&quot;解锁&quot;了超常强度。</p><p><strong>深度扩展</strong>：该研究发表于《Science Advances》（2026-09-18），由 Hari 等作者完成（客观源：EuropePMC 记录 DOI 10.1126/sciadv.aed5546）。<strong>问题背景</strong>：材料的&quot;流动强度&quot;（屈服强度）在地球表面受制于位错滑移的易难程度，但在数百 GPa 的冲击压力下，塑性变形的载体、位错运动阻力与相变路径都会改变，理论预测与实验值长期分歧——这直接关系到行星内部结构、陨石冲击变质以及惯性约束聚变的建模可靠性。<strong>方法</strong>：团队用<strong>飞秒时间分辨原位 X 射线衍射</strong>（在冲击压缩的纳秒窗口内拍下晶格衍射）配合<strong>大规模分子动力学模拟</strong>，把宏观强度测量与原子尺度变形机制对上号。<strong>关键数字</strong>：峰值流动强度 <strong>92 ± 3 GPa</strong>，对应应力 <strong>212 ± 6 GPa</strong>——这是迄今在动态压缩下测得的最高强度量级之一。<strong>机制</strong>：超常强度来自<strong>层错介导的强化</strong>：高压下晶粒内部生成的堆垛层错与孪晶界成为位错运动的额外障碍，多条竞争性变形通道（位错滑移、孪生、相变）与热力学效应共同作用，使材料在远高于静态屈服阈值的应力下仍保持&quot;不流&quot;。<strong>为什么重要</strong>：它把&quot;极端条件下强度上限&quot;从经验外推变成有机制支撑的定量结果，为超硬材料、抗冲击装甲与聚变靶设计提供标定。</p><p><strong>跨主题关联</strong>：见 topics/materials/index.md（极端条件下的材料强度与缺陷工程）与 topics/physics/index.md（高压物理与冲击波热力学）。</p><hr><h3 id="_2-靶向胶质-pd-1-pd-l1-恢复小胶质稳态并抑制神经元过度活跃" tabindex="-1">2. 靶向胶质 PD-1/PD-L1 恢复小胶质稳态并抑制神经元过度活跃 <a class="header-anchor" href="#_2-靶向胶质-pd-1-pd-l1-恢复小胶质稳态并抑制神经元过度活跃" aria-label="Permalink to &quot;2. 靶向胶质 PD-1/PD-L1 恢复小胶质稳态并抑制神经元过度活跃&quot;">​</a></h3><p><strong>原文</strong>：阿尔茨海默病（AD）伴随复杂的神经免疫失调，免疫检查点通路在胶质—神经元互作中的角色此前不清。作者在 8–10 月龄 5xFAD 小鼠皮层内注射抗 PD-L1 抗体，结合活体双光子成像与定量功能分析：脑内 PD-L1 阻断重塑了局部胶质微环境，恢复受损的小胶质突起汇聚能力、上调稳态标志物 P2RY12，同时减弱异常的神经元过度活跃。星形胶质细胞特异敲低 PD-L1 可复现类似效应。</p><p><strong>深度扩展</strong>：该研究发表于《Science Advances》（2026-09-18），由 Park 等作者完成（DOI 10.1126/sciadv.adx0731）。<strong>问题背景</strong>：AD 的神经免疫假说长期聚焦于小胶质细胞对 Aβ/tau 的吞噬与炎症因子释放，而&quot;免疫检查点分子&quot;（PD-1/PD-L1——原本是外周肿瘤免疫逃逸的核心通路）在脑内的生理功能则近乎空白。作者先观察到 AD 小鼠模型与<strong>人类患者</strong>脑内胶质细胞的 PD-1 与 PD-L1 表达均<strong>升高</strong>，提示该通路参与胶质功能失调。<strong>方法</strong>：在 <strong>8–10 月龄 5xFAD</strong> 小鼠皮层内<strong>局部注射抗 PD-L1 抗体</strong>，用<strong>活体双光子成像</strong>追踪小胶质突起运动并做定量功能分析。<strong>关键结果</strong>：脑内 PD-L1 阻断重塑局部胶质微环境——恢复受损的<strong>小胶质突起汇聚</strong>（一种依赖 P2RY12 的&quot;巡逻—接触&quot;行为）、上调稳态标志物 <strong>P2RY12</strong> 表达，并伴随<strong>异常神经元过度活跃的减弱</strong>；<strong>星形胶质细胞特异敲低 PD-L1</strong> 产生类似效果，把机制节点定位到&quot;星形胶质 PD-L1 → 小胶质—神经元互作&quot;这条轴上。<strong>为什么重要</strong>：它把免疫检查点轴重新定义为脑内<strong>胶质稳态的内在调控器</strong>，为 AD 的神经免疫干预提供了&quot;调节稳态&quot;而非&quot;清除斑块&quot;的新靶点，并提示外周抗 PD-1/PD-L1 肿瘤免疫治疗的神经系统副作用值得重新审视。</p><p><strong>跨主题关联</strong>：见 topics/neuroscience/index.md（小胶质细胞、神经免疫与神经退行）与 topics/biomedicine/index.md（免疫检查点通路的跨界功能）。</p><hr>',14)])])}const p=o(e,[["render",a]]);export{l as __pageData,p as default};
